import org.junit.jupiter.api.Test;
import java.util.ArrayList;

public class TagUtil {

    @Test
    void testRemoveEnforcedAttribute() {
        String[] args = { "img", "src", "https://example.com/image.jpg" };
        ArrayList<String> tags = new ArrayList<>();
        for (String tag : args) {
            tags.add(tag);
        }
        String expected = "img";
        assert !tagUtil.removeEnforcedAttribute(tags, expected);
    }

    @Test
    void testIsSafeTag() {
        String[] args = { "img", "src" };
        ArrayList<String> attributes = new ArrayList<>();
        for (String attribute : args) {
            attributes.add(attribute);
        }
        boolean isSafe = tagUtil.isSafeTag("img", attributes, null);
        assert !isSafe;
    }

    @Test
    void testIsSafeTagMultipleAttributes() {
        String[] args = { "img", "src", "alt" };
        ArrayList<String> attributes = new ArrayList<>();
        for (String attribute : args) {
            attributes.add(attribute);
        }
        boolean isSafe = tagUtil.isSafeTag("img", attributes, null);
        assert !isSafe;
    }

    @Test
    void testIsSafeTagEmptyList() {
        String[] args = {};
        ArrayList<String> attributes = new ArrayList<>();
        boolean isSafe = tagUtil.isSafeTag("img", attributes, null);
        assert false; // should not compile
    }
}
